import { memo } from "react";
import { LightBackground, type LightBackgroundProps } from "./light-background.shared";

export type LightRayBackgroundProps = LightBackgroundProps;

export const LightRayBackground = memo(function LightRayBackground({
  intensity = 1,
  speed = 0.1,
  ...props
}: LightRayBackgroundProps = {}) {
  return <LightBackground {...props} intensity={intensity} speed={speed} variant="light-ray" />;
});

"use client";

import { memo, useEffect, useRef, type ComponentProps } from "react";
import { useReducedMotion, useSpring } from "motion/react";
import { createShaderRenderer } from "./shader-renderer.shared";
import { cn } from "cn";
import ledShader from "./led-background.wgsl";
import lightRayShader from "./light-ray-background.wgsl";

export interface LightBackgroundProps extends ComponentProps<"div"> {
  speed?: number;
  interactive?: boolean;
  intensity?: number;
}

export const LightBackground = memo(function LightBackground({
  variant,
  speed = 1,
  interactive = true,
  intensity = 0.65,
  className,
  children,
  ...props
}: LightBackgroundProps & { variant: "led" | "light-ray" }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hostRef = useRef<HTMLDivElement>(null);
  const reducedMotion = useReducedMotion();
  const hover = useSpring(0, { stiffness: 180, damping: 24 });
  const brightness = Number.isFinite(intensity) ? Math.max(0, Math.min(2, intensity)) : 0.65;
  const rate = Number.isFinite(speed) ? Math.max(0, speed) : 1;

  useEffect(() => {
    const canvas = canvasRef.current;
    const host = hostRef.current;
    if (!canvas || !host) return;
    let pointer = [0.5, 0.5];
    const smoothed = [0.5, 0.5];
    let previousTime = 0;
    let surgeStart = -10;
    const track = (event: PointerEvent) => {
      if (!interactive || reducedMotion || event.pointerType === "touch") return;
      const bounds = host.getBoundingClientRect();
      if (!bounds.width || !bounds.height) return;
      pointer = [
        (event.clientX - bounds.left) / bounds.width,
        (event.clientY - bounds.top) / bounds.height,
      ];
      hover.set(1);
    };
    const leave = () => {
      hover.set(0);
    };
    const surge = () => {
      if (variant === "light-ray" && interactive && !reducedMotion) surgeStart = previousTime;
    };
    host.addEventListener("pointerdown", surge);
    host.addEventListener("pointermove", track);
    host.addEventListener("pointerleave", leave);
    host.addEventListener("pointercancel", leave);
    const cleanup = () => {
      host.removeEventListener("pointerdown", surge);
      host.removeEventListener("pointermove", track);
      host.removeEventListener("pointerleave", leave);
      host.removeEventListener("pointercancel", leave);
      hover.jump(0);
      renderer.dispose();
    };
    const uniforms = (elapsed: number, size: readonly [number, number]) => {
      const dt = Math.min(0.05, Math.max(0, elapsed - previousTime));
      previousTime = elapsed;
      const follow = 1 - Math.exp(-dt / 0.6);
      for (let i = 0; i < 2; i++) smoothed[i] += (pointer[i] - smoothed[i]) * follow;
      const age = elapsed - surgeStart;
      const reveal = reducedMotion || rate === 0 ? 1 : Math.min(1, elapsed / 1.8);
      return {
        cfg: {
          metrics: [size[0], size[1], elapsed * rate, brightness],
          pointer: [
            ...(variant === "light-ray" ? smoothed : pointer),
            reducedMotion ? 0 : hover.get(),
            0,
          ],
          ...(variant === "light-ray"
            ? {
                animation: [
                  elapsed * (rate + 0.2),
                  1.7 - reveal * reveal * (3 - 2 * reveal) * 3.6,
                  -0.6 + age * 2.6,
                  age < 2.4 ? Math.min(1, age / 0.12) * Math.exp(-age * 1.1) : 0,
                ],
              }
            : {}),
        },
      };
    };
    const renderer = createShaderRenderer(canvas, variant === "led" ? ledShader : lightRayShader, {
      label: `${variant}-background`,
      uniforms,
      animated: !reducedMotion && (rate > 0 || interactive),
      fps: variant === "light-ray" ? 60 : 30,
    });
    return cleanup;
  }, [variant, rate, interactive, reducedMotion, hover, brightness]);

  return (
    <div
      {...props}
      ref={hostRef}
      data-slot={`${variant}-background`}
      className={cn(
        "hangry-background relative isolate min-h-96 overflow-hidden border border-border bg-background",
        className,
      )}
    >
      <div aria-hidden="true" className="pointer-events-none absolute inset-0 -z-10">
        <div
          className="absolute inset-0 hidden dark:block"
          style={
            variant === "led"
              ? {
                  backgroundImage: "radial-gradient(circle, #334155 1px, transparent 2px)",
                  backgroundSize: "16px 16px",
                }
              : {
                  backgroundImage:
                    "repeating-conic-gradient(from 12deg, #000 0deg 5deg, #333 5.2deg 5.5deg, #000 5.8deg 12deg)",
                }
          }
        />
        <div
          className="absolute inset-0 dark:hidden"
          style={{
            background:
              variant === "led"
                ? "radial-gradient(circle, #234a67 1px, #e6f0f7 2px) 0 0 / 16px 16px"
                : "repeating-conic-gradient(from 12deg, #edf5fa 0deg 5deg, #57758c 5.2deg 5.5deg, #edf5fa 5.8deg 12deg)",
          }}
        />
        <canvas ref={canvasRef} className="absolute inset-0 block h-full w-full opacity-0" />
      </div>
      {children}
    </div>
  );
});

import { lightBlue, lightCyan, lightPaper } from "./light-palette.shared.wgsl";

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

struct Config {
  metrics: vec4f, // canvas width, height, time, intensity
  pointer: vec4f, // normalized position, hover strength, reserved
};
@group(0) @binding(0) var<uniform> cfg: Config;

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let pixel = uv * cfg.metrics.xy;
  let spacing = 16.0;
  let cell = floor(pixel / spacing);
  let local = fract(pixel / spacing) - 0.5;
  let radius = length(local) * spacing;
  let led = 1.0 - smoothstep(1.2, 2.0, radius);
  let halo = exp(-radius * radius / 12.0);
  let scanX = (sin(cfg.metrics.z * 0.22) * 0.5 + 0.5) * cfg.metrics.x;
  let scan = exp(-pow((pixel.x - scanX + pixel.y * 0.2) / 120.0, 2.0));
  let cursor = pixel - cfg.pointer.xy * cfg.metrics.xy;
  let hover = exp(-dot(cursor, cursor) / 20000.0) * cfg.pointer.z;
  let variation = 0.8 + fract(sin(dot(cell, vec2f(127.1, 311.7))) * 43758.5453) * 0.2;
  let energy = (led * (0.11 + scan * 0.5 + hover * 0.65) + halo * (scan + hover) * 0.07) * variation;
  let vignette = 1.0 - smoothstep(0.2, 0.85, length(uv - 0.5)) * 0.5;
  if (theme.mode.x > 0.5) {
    let board = lightPaper();
    let solidDot = 1.0 - smoothstep(1.8, 2.7, radius);
    let dotColor = mix(lightBlue(), lightCyan(), clamp(scan * 0.75 + hover * 0.25, 0.0, 1.0));
    let coverage = solidDot * (0.8 + scan * 0.2 + hover * 0.15) * variation * cfg.metrics.w;
    return vec4f(mix(board, dotColor, clamp(coverage, 0.0, 1.0)), 1.0);
  }
  let color = vec3f(0.008, 0.012, 0.018) + vec3f(0.62, 0.8, 1.0) * energy * vignette * cfg.metrics.w;
  return vec4f(color, 1.0);
}

import { lightCyan, lightPaper } from "./light-palette.shared.wgsl";

struct Theme { mode: vec4f };
@group(1) @binding(0) var<uniform> theme: Theme;

struct Config {
  metrics: vec4f,    // x, y: size px · z: pulse clock · w: intensity
  pointer: vec4f,    // xy: pointer 0..1 (y down) · z: steer strength
  animation: vec4f,  // drift, reveal threshold, surge depth, surge strength
};
@group(0) @binding(0) var<uniform> cfg: Config;
const TAU = 6.2831853;
const COUNT = 56.0;
const FLOW = -1.0;  // 1.0: pulses run into the tunnel, -1.0: out toward the viewer
fn hash(n: f32) -> f32 { return fract(sin(n * 127.1) * 43758.5453); }
fn bend_at(depth: f32) -> vec2f {
  let reach = 1.0 - exp(-max(depth, 0.0) * 0.55);
  let wobble = vec2f(sin(cfg.animation.x * 0.37 + depth * 0.31), cos(cfg.animation.x * 0.29 + depth * 0.23)) * 0.18;
  let steer = (cfg.pointer.xy - 0.5) * vec2f(1.0, -1.0) * 0.5 * cfg.pointer.z;
  return (wobble + steer) * reach;
}
@fragment
fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let scale = min(cfg.metrics.x, cfg.metrics.y) * 0.5;
  let p = (uv - 0.5) * cfg.metrics.xy * vec2f(1.0, -1.0) / scale;
  var depth = -log(max(length(p), 0.00001));
  var q = p;
  for (var j = 0; j < 4; j++) {
    q = p - bend_at(depth);
    depth = -log(max(length(q), 0.00001));
  }
  let r = length(q);
  let px = r * scale;
  let swing = sin(cfg.animation.x * 0.9) * 0.25 / TAU;
  let s = atan2(q.y, q.x) / TAU - swing - 0.045 * sin(depth * 1.2 + cfg.animation.x * 0.5);
  let cell = floor(s * COUNT);
  let spacing = TAU * px / COUNT;
  let near = smoothstep(0.55, 1.25, r);
  let width = 0.775 * (1.0 + near * 1.2);
  let soft = 0.55 + near * 0.9;
  let tight = 2.4 * (1.0 + near);
  var lines = 0.0;
  var glow = 0.0;
  for (var k = -3; k <= 3; k++) {
    let i = cell + f32(k);
    let id = i - floor(i / COUNT) * COUNT;
    let h1 = hash(id);
    let h2 = hash(id + 17.0);
    let h3 = hash(id + 41.0);
    let h4 = hash(id + 73.0);
    var center = (i + 0.5 + (h1 - 0.5) * 0.55) / COUNT;
    center += 0.12 * sin(depth * (0.8 + h2 * 0.9) + cfg.animation.x * (0.4 + h3 * 0.5) + h4 * TAU) / COUNT;
    let d = abs(s - center) * TAU * px;
    let shade = 1.0 + (h3 - 0.5) * 0.9;
    let reach = 1.0 - smoothstep(spacing * 1.4, max(spacing * 2.4, 0.00001), d);
    lines += (1.0 - smoothstep(width - soft, width + soft, d)) * shade;
    // FLOW flips the travel direction. The head/tail sides flip with it, so the head always leads.
    let x = depth * 0.4 - FLOW * cfg.metrics.z * 8.0 * (0.55 + h2 * 0.6) + h4 * 7.0;
    let lead = -FLOW * (fract(x) - 0.5) / 0.4;
    let lit = select(0.0, 1.0, hash(id * 3.7 + floor(x) * 13.1) <= 0.5);
    let ahead = max(-lead, 0.0) / 0.071232;
    let head = exp(-ahead * ahead) * smoothstep(-1.25, -1.0, lead);
    let tail = exp(-max(lead, 0.0) / 0.30912) * (1.0 - smoothstep(0.6875, 1.25, lead));
    let off = (depth - cfg.animation.z) / 0.22;
    let surge = cfg.animation.w * exp(-off * off);
    let pulse = max(select(tail, head, lead < 0.0) * lit, surge);
    let core = 1.5 * width + 0.35;
    let stroke = 1.0 - smoothstep(core - soft, core + soft, d);
    let bloom = (exp(-d / tight) * 0.7 + exp(-d / (tight * 4.5)) * 0.18) * reach;
    glow += pulse * (stroke * 1.5 + bloom) * shade;
  }
  let lod = 1.0 - smoothstep(1.2, 4.0, spacing);
  let average = min(1.55 / max(spacing, 0.001), 1.0);
  lines = mix(lines, average, lod);
  glow = mix(glow, average * 0.3, lod);
  let rr = r * 0.25;
  let fade = smoothstep(0.0, 0.5, rr) * (1.0 - smoothstep(1.1, 2.0, rr)) * smoothstep(cfg.animation.y - 0.6, cfg.animation.y, depth);
  let light = (lines * 0.12 + glow) * cfg.metrics.w * fade;
  if (theme.mode.x > 0.5) {
    let beam = 1.0 - exp(-light * 1.8);
    return vec4f(mix(lightPaper(), lightCyan(), beam), 1.0);
  }
  return vec4f(vec3f(1.0 - exp(-light * 1.4)), 1.0);
}

import {
  effect,
  frame,
  frameLoop,
  init,
  sampler,
  surface,
  target,
  type Frame,
  type SurfaceOptions,
} from "vgpu";

type ShaderSource = Parameters<typeof effect>[1];
type Bindings = Parameters<ReturnType<typeof effect>["set"]>[0];

export interface PostProcessOptions {
  label: string;
  source: ShaderSource;
  uniforms?: (time: number, size: readonly [number, number]) => Bindings;
}

interface ShaderRendererOptions {
  label: string;
  uniforms: (time: number, size: readonly [number, number]) => Bindings;
  animated?: boolean;
  fps?: number;
  surface?: SurfaceOptions;
  postProcess?: PostProcessOptions;
  themeAware?: boolean;
  themeMask?: boolean;
}

/** Owns one canvas effect. Components supply bindings and retain their own input/UI logic. */
export function createShaderRenderer(
  canvas: HTMLCanvasElement,
  source: ShaderSource,
  {
    label,
    uniforms,
    animated = true,
    fps = 60,
    surface: surfaceOptions = { dpr: 1 },
    postProcess,
    themeAware = true,
    themeMask = false,
  }: ShaderRendererOptions,
) {
  let disposed = false;
  let gpu: Awaited<ReturnType<typeof init>> | undefined;
  let output: ReturnType<typeof surface> | undefined;
  let scene: ReturnType<typeof target> | undefined;
  let themeObserver: MutationObserver | undefined;
  let light = themeAware && !document.documentElement.classList.contains("dark");
  const theme = () => ({ mode: [Number(light), Number(themeMask), 0, 0] });
  let sceneSampler: ReturnType<typeof sampler> | undefined;
  let shader: ReturnType<typeof effect> | undefined;
  let postShader: ReturnType<typeof effect> | undefined;
  let loop: ReturnType<typeof frameLoop> | undefined;
  let observer: ResizeObserver | undefined;
  let unsubscribeResize: (() => void) | undefined;
  let pendingFrame = 0;
  let draw: ((currentFrame: Frame) => void) | undefined;
  canvas.style.opacity = "0";

  const dispose = () => {
    if (disposed) return;
    disposed = true;
    loop?.stop();
    observer?.disconnect();
    themeObserver?.disconnect();
    cancelAnimationFrame(pendingFrame);
    unsubscribeResize?.();
    shader?.dispose();
    postShader?.dispose();
    output?.dispose();
    gpu?.dispose();
  };
  const render = () => {
    if (disposed || !draw || animated) return;
    cancelAnimationFrame(pendingFrame);
    pendingFrame = requestAnimationFrame(() => {
      if (!disposed && gpu && draw) frame(gpu, draw);
    });
  };
  const start = async () => {
    const initialized = await init();
    if (disposed) {
      initialized.dispose();
      return;
    }
    gpu = initialized;
    output = surface(gpu, canvas, surfaceOptions);
    scene = postProcess ? target(gpu, { size: output.size }) : undefined;
    sceneSampler = postProcess
      ? sampler(gpu, { minFilter: "linear", magFilter: "linear" })
      : undefined;
    light = themeAware && !document.documentElement.classList.contains("dark");
    shader = effect(gpu, source, {
      label,
      set: { ...uniforms(0, (scene ?? output).size), theme: theme() },
    });
    postShader = postProcess
      ? effect(gpu, postProcess.source, {
          label: postProcess.label,
          set: {
            theme: theme(),
            scene: scene,
            sceneSampler,
            ...postProcess.uniforms?.(0, output.size),
          },
        })
      : undefined;
    await shader.compile(scene ?? output);
    await postShader?.compile(output);
    if (disposed) return;
    const startedAt = performance.now();
    if (output && scene && sceneSampler) {
      unsubscribeResize = output.onResize(({ width, height }) => {
        scene?.resize([width, height]);
        postShader?.set({
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(0, [width, height]),
        });
      });
    }
    draw = (currentFrame) => {
      if (!output || !shader || disposed) return;
      const time = animated ? (performance.now() - startedAt) / 1000 : 0;
      const renderTarget = scene ?? output;
      shader.set({ ...uniforms(time, renderTarget.size), theme: theme() });
      if (postShader && scene && sceneSampler) {
        postShader.set({
          theme: theme(),
          scene,
          sceneSampler,
          ...postProcess?.uniforms?.(time, output.size),
        });
        currentFrame.pass(scene, shader);
        currentFrame.pass(output, postShader);
      } else {
        currentFrame.pass(scene ?? output, shader);
      }
      canvas.style.opacity = "1";
    };
    if (themeAware) {
      themeObserver = new MutationObserver(() => {
        light = themeAware && !document.documentElement.classList.contains("dark");
        render();
      });
      themeObserver.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class"],
      });
    }
    if (animated) loop = frameLoop(gpu, draw, { fps });
    else {
      observer = new ResizeObserver(render);
      observer.observe(canvas);
      render();
    }
  };
  void start().catch((error: unknown) => {
    if (!disposed) {
      canvas.style.opacity = "0";
      console.warn(`${label} could not start; retaining its fallback:`, error);
      dispose();
    }
  });
  return { dispose, render };
}

// Dedicated pigments for light-mode shader materials. No output filtering.
export fn lightPaper() -> vec3f { return vec3f(0.9568627, 0.9803922, 0.9647059); }
export fn lightSurface() -> vec3f { return vec3f(0.8470588, 0.9333333, 0.8862745); }
export fn lightInk() -> vec3f { return vec3f(0.0666667, 0.2352941, 0.1960784); }
export fn lightEmerald() -> vec3f { return vec3f(0.0000000, 0.4862745, 0.3450980); }
export fn lightCyan() -> vec3f { return vec3f(0.0000000, 0.5450980, 0.7215686); }
export fn lightBlue() -> vec3f { return vec3f(0.1568627, 0.3686275, 0.9098039); }
export fn lightViolet() -> vec3f { return vec3f(0.5098039, 0.2666667, 0.8470588); }
export fn lightRose() -> vec3f { return vec3f(0.8392157, 0.2352941, 0.5137255); }
export fn lightGold() -> vec3f { return vec3f(0.8431373, 0.5764706, 0.1137255); }
